def replace_js_function(text, name, new_code):
    needle = 'function ' + name + '('
    start = text.find(needle)
    if start < 0: raise SystemExit('Missing function ' + name)
    brace = text.find('{', start)
    depth = 0; quote = None; escp = False; i = brace
    while i < len(text):
        ch = text[i]
        if quote:
            if escp: escp = False
            elif ch == '\\': escp = True
            elif ch == quote: quote = None
        else:
            if ch in ("'", '"', '`'): quote = ch
            elif ch == '{': depth += 1
            elif ch == '}':
                depth -= 1
                if depth == 0: return text[:start] + new_code + text[i+1:]
        i += 1
    raise SystemExit('Unclosed function ' + name)

def insert_before(text, needle, block):
    marker = block.splitlines()[0].strip()
    if marker and marker in text: return text
    pos = text.find(needle)
    if pos < 0: raise SystemExit('Insert marker not found: ' + needle)
    return text[:pos] + block + '\n' + text[pos:]

